function rect(p,x,y,w,h,c="#ffffff",border="#dbe0e6"){const n=figma.createRectangle();p.appendChild(n);n.x=x;n.y=y;n.resize(w,h);n.fills=[{type:"SOLID",color:rgb(c)}];n.strokes=[{type:"SOLID",color:rgb(border)}];return n;}
